mapper.select:
SELECT id, operator_id, module, action, target_id, target_type,
       detail, ip_address, create_time
FROM t_operation_log


        AND module = #{module}


        AND operator_id = #{operatorId}


ORDER BY create_time DESC

SELECT l.id, l.operator_id, u.username AS operator_name, l.module, l.action, l.target_id, l.target_type, l.detail, l.ip_address, l.create_time AS operation_time FROM t_operation_log l LEFT JOIN t_user u ON u.id = l.operator_id AND u.is_deleted = 0
AND l.module = #{module}
AND l.operator_id = #{operatorId}
ORDER BY l.create_time DESC

SELECT l.id, l.operator_id, u.username AS operator_name, l.module, l.action, l.target_id, l.target_type, l.detail, l.ip_address, l.create_time AS operation_time FROM t_operation_log l LEFT JOIN t_user u ON u.id = l.operator_id AND u.is_deleted = 0
AND l.module = #{module}
ORDER BY l.create_time DESC LIMIT #{limit}
